package com.aistock.market.refresh;
import com.aistock.market.alert.AlertEvidenceRecords;
import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AlertEvidenceCollectorHttpTest {
 @Test void boundedRealHttpContractRejectsCoercedCalendarFlags()throws Exception{
  var body=new AtomicReference<>("{\"state\":\"SOURCE_BUSY\",\"candidate\":null,\"errorCode\":\"SOURCE_BUSY\"}");var sent=new AtomicReference<String>();var auth=new AtomicReference<String>();
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/market/alert-collect",exchange->{sent.set(new String(exchange.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));auth.set(exchange.getRequestHeaders().getFirst("X-Service-Token"));var bytes=body.get().getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});server.start();
  try{var client=new AlertEvidenceCollectorClient("http://127.0.0.1:"+server.getAddress().getPort(),"fixture");var req=new AlertEvidenceRecords.Request(UUID.randomUUID(),"SH600030",UUID.randomUUID(),LocalDate.of(2026,10,9),Instant.now().plusSeconds(90));var result=client.collect(req,LocalDate.of(2026,10,8));assertEquals("SOURCE_BUSY",result.state());var json=new ObjectMapper().readTree(sent.get());assertEquals("2026-10-08",json.path("start").asText());assertEquals("2026-10-09",json.path("calendarThrough").asText());assertEquals("fixture",auth.get());
   body.set("{\"state\":\"AVAILABLE\",\"errorCode\":null,\"candidate\":{\"calendar\":[{\"date\":\"2026-10-09\",\"open\":1}],\"bars\":[]}}");assertEquals("SOURCE_INVALID",client.collect(req,LocalDate.of(2026,10,8)).state());
   var n=new java.math.BigDecimal("100");var raw=new com.aistock.market.quotation.RawBar(req.tradeDate(),n,n,n,n,n,n,1,null);var c=new com.aistock.market.forecast.ForecastCandidate(req.operationId().toString(),req.instrumentId(),req.rawVersionId().toString(),"baostock","baostock-backward-close-over-raw-v1",Instant.now(),"a".repeat(64),List.of(new com.aistock.market.forecast.ForecastCandidate.PairedBar(raw,n)),List.of(new com.aistock.market.quotation.TradingDay(req.tradeDate(),true)));var mapper=new ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);var tree=mapper.createObjectNode();tree.put("state","AVAILABLE");tree.putNull("errorCode");tree.set("candidate",mapper.valueToTree(c));body.set(mapper.writeValueAsString(tree));assertEquals("AVAILABLE",client.collect(req,LocalDate.of(2026,10,8)).state());
   var point=(com.fasterxml.jackson.databind.node.ObjectNode)tree.path("candidate").path("bars").get(0);point.putRawValue("backwardClose",new com.fasterxml.jackson.databind.util.RawValue("100.0000000000000000001"));body.set(mapper.writeValueAsString(tree));assertTrue(body.get().contains("100.0000000000000000001"));assertEquals("100.0000000000000000001",client.collect(req,LocalDate.of(2026,10,8)).candidate().bars().get(0).backwardClose().toPlainString());point.putRawValue("backwardClose",new com.fasterxml.jackson.databind.util.RawValue("1234567890123456.123456789012"));body.set(mapper.writeValueAsString(tree));assertEquals("1234567890123456.123456789012",client.collect(req,LocalDate.of(2026,10,8)).candidate().bars().get(0).backwardClose().toPlainString());
   body.set("x".repeat(131073));assertEquals("SOURCE_INVALID",client.collect(req,LocalDate.of(2026,10,8)).state());
  }finally{server.stop(0);}
 }

 @Test void headersDoNotDisableFullResponseDeadline()throws Exception{
  var release=new java.util.concurrent.CountDownLatch(1);var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/market/alert-collect",exchange->{exchange.getRequestBody().readAllBytes();exchange.sendResponseHeaders(200,0);exchange.getResponseBody().write('{');exchange.getResponseBody().flush();try{release.await(40,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{exchange.close();}});server.start();var pool=java.util.concurrent.Executors.newSingleThreadExecutor();
  try{var client=new AlertEvidenceCollectorClient("http://127.0.0.1:"+server.getAddress().getPort(),"fixture");var req=new AlertEvidenceRecords.Request(UUID.randomUUID(),"SH600030",UUID.randomUUID(),LocalDate.of(2026,10,9),Instant.now().plusSeconds(90));var pending=pool.submit(()->client.collect(req,LocalDate.of(2026,10,8)));assertEquals("SOURCE_TIMEOUT",pending.get(32,java.util.concurrent.TimeUnit.SECONDS).state());}finally{release.countDown();server.stop(0);pool.shutdownNow();}
 }
}
